package com.school.management.entity;
import jakarta.persistence.*;import jakarta.validation.constraints.*;import com.fasterxml.jackson.annotation.JsonProperty;import java.time.LocalDate;
@Entity public class Student { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(unique=true,nullable=false) private String admissionNo; @NotBlank private String fullName; @Email private String email; private String phone,gender,address,parentName,parentPhone; private LocalDate dateOfBirth; private String className; @JsonProperty(access = JsonProperty.Access.WRITE_ONLY) private String password; private String photoUrl; public Student(){} public Long getId(){return id;} public String getAdmissionNo(){return admissionNo;} public void setAdmissionNo(String v){admissionNo=v;} public String getFullName(){return fullName;} public void setFullName(String v){fullName=v;} public String getEmail(){return email;} public void setEmail(String v){email=v;} public String getPhone(){return phone;} public void setPhone(String v){phone=v;} public String getGender(){return gender;} public void setGender(String v){gender=v;} public String getAddress(){return address;} public void setAddress(String v){address=v;} public String getParentName(){return parentName;} public void setParentName(String v){parentName=v;} public String getParentPhone(){return parentPhone;} public void setParentPhone(String v){parentPhone=v;} public LocalDate getDateOfBirth(){return dateOfBirth;} public void setDateOfBirth(LocalDate v){dateOfBirth=v;} public String getClassName(){return className;} public void setClassName(String v){className=v;} public String getPassword(){return password;} public void setPassword(String v){password=v;} public String getPhotoUrl(){return photoUrl;} public void setPhotoUrl(String v){photoUrl=v;} }
